import { 
  MeshBasicNodeMaterial, 
  PlaneGeometry,
  Mesh,
  Group
} from 'three/webgpu';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh, PlaneGeometry: ThreePlaneGeometry, Color } = ctx.THREE;

  const root = new ThreeGroup();
  const cleanupTasks = [];

  // 1. STAGE & PALETTE SETUP
  // Color palette from spec
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    surface: "#0b0b10"
  };

  // Define dimensions based on atlas region: 512 x 320
  const width = 3.5;
  const height = (320 / 512) * width; // Preserve aspect ratio (~2.18)

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false
  });

  const spriteMesh = new Mesh(geometry, material);
  root.add(spriteMesh);

  // Load the sprite asset
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      material.colorNode = texture;
      material.needsUpdate = true;
    }).catch((err) => {
      console.warn("Failed loading sprite texture:", err);
    });
  }

  // Accent backlighting or subtle rim illumination to ground the sprite
  // Soft ambient setup is provided by the global scene, we only need to position local elements.
  spriteMesh.position.set(0, 0, 0);

  // Subtle breathing idle animation (weight with soft power eases)
  const idleTimeline = gsap.timeline({ repeat: -1, yoyo: true });
  idleTimeline.to(spriteMesh.position, {
    y: 0.08,
    duration: 3.5,
    ease: "power1.inOut"
  });
  cleanupTasks.push(() => idleTimeline.kill());

  // Rise-in entry animation
  spriteMesh.position.y = -0.4;
  spriteMesh.scale.set(0.95, 0.95, 0.95);
  const entryTimeline = gsap.timeline();
  entryTimeline.to(spriteMesh.position, {
    y: 0,
    duration: 1.2,
    ease: "power4.out"
  });
  entryTimeline.to(spriteMesh.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 1.2,
    ease: "power4.out"
  }, "<");
  cleanupTasks.push(() => entryTimeline.kill());

  // 2. CLEANUP HANDLER
  root.userData = {
    cleanup() {
      cleanupTasks.forEach(task => task());
      geometry.dispose();
      material.dispose();
    }
  };

  return root;
}
